@startuml

class Bettor {
  + bettorId : string
  + name : string
}

class Race {
  + raceId : string
  + raceName : string
}

class Runner {
  + runnerId : string
  + horseName : string
}

class Jockey {
  + jockeyId : string
  + name : string
}

class Bet {
  + betId : string
  + amount : float
  + odds : float
}

Bettor "1" -- "*" Bet
Race "1" *-- "1..*" Runner
Runner "1" -- "1" Jockey
Bet "*" -- "1" Race
Bet "*" -- "1" Runner

@enduml

